-- Lot 230 : payloads 871 a 900 sur 1299.
--
-- Chaque commande recoit un texte propre a ChatGPT, a Claude et a Gemini.
-- Rien n'est supprime : l'ancienne version quitte le courant et reste lisible
-- dans l'historique, ce qui suffit a revenir en arriere.

drop table if exists lot_v5_payloads;
create temporary table lot_v5_payloads as
select * from jsonb_to_recordset($raccourcia$[{"ref":"RCI-IMG-303","moteur":"chatgpt","payload":"[RaccourcIA — /storybook]\n\nMISSION\nTransformer un sujet en illustration de livre jeunesse. Personnages constants, action simple, détails adaptés à l’âge fourni et palette douce. Aucun texte d’histoire ajouté sauf demande explicite.\n\nDÉCISION\nAnalyse le message, l’historique utile et chaque image jointe. Si un outil de génération ou d’édition d’image est disponible, utilise-le avec les références exactes. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Quelle intensité d’effet souhaites-tu : subtile, marquée ou choisis pour moi ?. Accepte « Choisis pour moi », décide professionnellement et continue. Ne redemande rien de visible ou déjà fourni. Une préférence facultative ne bloque jamais la production.\n\nEXÉCUTION\nProduis « Illustration jeunesse » avec une composition lisible, une perspective cohérente, une lumière crédible et des matières adaptées. Personnages constants, action simple, détails adaptés à l’âge fourni et palette douce. Aucun texte d’histoire ajouté sauf demande explicite. Le format par défaut est 1:1 en haute définition; adapte-le au canal explicite. N’ajoute aucun texte sauf demande explicite.\n\nPRÉSERVER\nConserve le sujet, sa silhouette, ses proportions et ses détails distinctifs; ne transforme que l’effet demandé.\n\nÉVITER\nÉvite effet générique, sujet méconnaissable, texture répétitive, contours fusionnés, surtraitement et éléments ajoutés sans intention. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique technique, logo ou texte officiel. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Avant de livrer, vérifie silencieusement fidélité du sujet, proportions, perspective, lumière, ombres, anatomie, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. fidélité; impact; lisibilité; composition; lumière; perspective; matière; texte; absence d’artefacts Si aucun outil image n’est accessible, fournis le prompt final prêt à exécuter et indique en une phrase que l’image n’a pas été générée.","sha256":"aa10d7dc3471ebf60f1b07fa10ebdc773babc5ab4425e6fc057b0f06d15b0dbf"},{"ref":"RCI-IMG-303","moteur":"claude","payload":"[RaccourcIA — /storybook]\n\nMISSION\nTransformer un sujet en illustration de livre jeunesse. Personnages constants, action simple, détails adaptés à l’âge fourni et palette douce. Aucun texte d’histoire ajouté sauf demande explicite.\n\nDÉCISION\nRepère d’abord les contraintes dans les images et documents, puis consolide-les sans longue reformulation. Vérifie les capacités réellement disponibles avant toute production. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Quelle intensité d’effet souhaites-tu : subtile, marquée ou choisis pour moi ?. Accepte « Choisis pour moi », décide professionnellement et continue. Ne redemande rien de visible ou déjà fourni. Une préférence facultative ne bloque jamais la production.\n\nEXÉCUTION\nProduis « Illustration jeunesse » avec une composition lisible, une perspective cohérente, une lumière crédible et des matières adaptées. Personnages constants, action simple, détails adaptés à l’âge fourni et palette douce. Aucun texte d’histoire ajouté sauf demande explicite. Le format par défaut est 1:1 en haute définition; adapte-le au canal explicite. N’ajoute aucun texte sauf demande explicite.\n\nPRÉSERVER\nConserve le sujet, sa silhouette, ses proportions et ses détails distinctifs; ne transforme que l’effet demandé.\n\nÉVITER\nÉvite effet générique, sujet méconnaissable, texture répétitive, contours fusionnés, surtraitement et éléments ajoutés sans intention. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique technique, logo ou texte officiel. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Avant de livrer, vérifie silencieusement fidélité du sujet, proportions, perspective, lumière, ombres, anatomie, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. fidélité; impact; lisibilité; composition; lumière; perspective; matière; texte; absence d’artefacts Sans moteur image connecté, livre un brief de transfert autonome, précis et exploitable. Ne prétends jamais avoir rendu ou inspecté une image inexistante.","sha256":"257a5917edebe8b1f9a434c401965406430e006e82df669e0748a225525a380e"},{"ref":"RCI-IMG-303","moteur":"gemini","payload":"[RaccourcIA — /storybook]\n\nMISSION\nTransformer un sujet en illustration de livre jeunesse. Personnages constants, action simple, détails adaptés à l’âge fourni et palette douce. Aucun texte d’histoire ajouté sauf demande explicite.\n\nDÉCISION\nInspecte visuellement toutes les pièces jointes avant le texte de contexte. Relie clairement chaque référence à son rôle : sujet, style, marque, données ou composition. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Quelle intensité d’effet souhaites-tu : subtile, marquée ou choisis pour moi ?. Accepte « Choisis pour moi », décide professionnellement et continue. Ne redemande rien de visible ou déjà fourni. Une préférence facultative ne bloque jamais la production.\n\nEXÉCUTION\nProduis « Illustration jeunesse » avec une composition lisible, une perspective